import sys
from math import isqrt

def main():
    input = sys.stdin.buffer.readline
    N, M = map(int, input().split())
    P = list(map(int, input().split()))

    def calc(x):
        total_cost = 0
        total_units = 0
        for p in P:
            k = (x + p) // (2 * p)
            total_units += k
            total_cost += k * k * p
            if total_cost > M:
                return total_cost, total_units
        return total_cost, total_units

    low, high = 0, 2 * isqrt(M * max(P)) + 2 * max(P) + 10

    while low < high:
        mid = (low + high + 1) // 2
        cost, _ = calc(mid)
        if cost <= M:
            low = mid
        else:
            high = mid - 1

    cost, units = calc(low)
    ans = units + (M - cost) // (low + 1)
    print(ans)

if __name__ == "__main__":
    main()
